/**
 * Parse incoming KB change event from pg_notify or Supabase webhook.
 * Supports: expert_rules changes, knowledge_items changes, manual trigger.
 *
 * Payload format (from fn_notify_knowledge_change):
 * { source_table, source_id, source_slug, story_id, action, title, category, tags, triggered_at }
 *
 * Per-story routing: when story_id is present, upload goes into Ragnarok
 * project_id='story-{story_id}' so Maestro queries scoped to that story
 * (already used by multi-turn USP test) find the document. Globals stay in
 * project_id='aisha'.
 */
const body = $input.first().json.body || $input.first().json;

const sourceTable = body.source_table || body.table || 'unknown';
const sourceId = body.source_id || body.record?.id || body.old_record?.id || 'unknown';
const sourceSlug = body.source_slug || body.record?.slug || body.record?.source_slug || 'unknown';
const storyId = body.story_id || body.record?.story_id || null;
const action = body.action || body.type || 'UPDATE';
const title = body.title || body.record?.title || '';
const category = body.category || body.record?.category || '';
const tags = body.tags || body.record?.ai_context_tags || [];
const triggeredAt = body.triggered_at || new Date().toISOString();

// Determine KB doc ID prefix
const kbIdPrefix = sourceTable === 'expert_rules' ? 'rule' : 'ki';
const kbId = `${kbIdPrefix}-${sourceSlug}`;
const projectId = storyId ? `story-${storyId}` : 'aisha';

return [{
  json: {
    sourceTable,
    sourceId,
    sourceSlug,
    storyId,
    kbId,
    projectId,
    action: action.toUpperCase(),
    title,
    category,
    tags,
    triggeredAt,
    isDelete: ['DELETE', 'DELETED', 'ARCHIVED'].includes(action.toUpperCase())
  }
}];

/**
 * AISHA Impact Evaluation — hodnotí dopad KB změny NA ÚROVNI PLATFORMY.
 * 
 * Toto NENÍ story-context evaluace — tady AISHA funguje jako strážce
 * celkového stavu KB a koherence knowledge base.
 * 
 * Vyhodnocuje:
 * 1. Je změna konzistentní s existujícími pravidly?
 * 2. Nesoupeří nové pravidlo/znalost s existujícím?
 * 3. Jsou všechny cross-reference intaktní?
 * 4. Potřebuje expert review?
 * 5. Jsou mezery v pokrytí po této změně?
 */
const change = $('Parse Change Event').item.json;
const syncResult = $input.first().json;
const syncOk = syncResult.statusCode === 200 || syncResult.ok === true;

// Severity classification based on change type
const severityMap = {
  'security_practice': 'HIGH',
  'architecture_pattern': 'HIGH',
  'coding_standard': 'MEDIUM',
  'api_design': 'MEDIUM',
  'testing_rule': 'LOW',
  'workflow': 'LOW',
};
const severity = severityMap[change.category] || 'MEDIUM';

// Impact assessment
const impactFactors = [];
if (['DELETE', 'DELETED', 'ARCHIVED'].includes(change.action)) {
  impactFactors.push('DELETION — potenciální ztráta kontextu');
}
if (change.category === 'security_practice') {
  impactFactors.push('SECURITY — vyžaduje bezpodmínečnou validaci');
}
if (change.tags?.some(t => ['critical', 'breaking', 'security'].includes(t))) {
  impactFactors.push('TAGGED CRITICAL — expert review povinný');
}
if (!syncOk) {
  impactFactors.push('SYNC FAILED — Ragnarok nedostupný nebo chybný upload');
}

const needsExpertReview = severity === 'HIGH'
  || impactFactors.length >= 2
  || !syncOk
  || change.action === 'DELETE';

// Build evaluation context for AISHA
const evaluation = {
  change_summary: `${change.action} ${change.sourceTable}/${change.sourceSlug}: ${change.title}`,
  ragnarok_sync: syncOk ? 'OK' : 'FAILED',
  severity,
  impact_factors: impactFactors,
  needs_expert_review: needsExpertReview,
  // AISHA's own context questions — what should she investigate next
  context_questions: [
    `Existují pravidla která závisí na ${change.sourceSlug}?`,
    `Mění tato změna celkový kontextový profil platformy?`,
    `Potřebuje expert ověřit konzistenci s aktuálním směrem projektu?`
  ],
  evaluated_at: new Date().toISOString()
};

return [{ json: evaluation }];

/**
 * Context Gap Detection — AISHA surfacuje potenciální mezery.
 * 
 * Principy:
 * - AISHA se nerozhoduje ZA uživatele, ale DOVYPLAVÍ informace
 * - Identifikuje cross-reference gaps (pravidlo odkazuje neexistující)
 * - Kontroluje pokrytí kritických oblastí (security, audit, i18n)
 * - Navrhuje konkrétní otázky pro expert review
 * 
 * Tento krok MŮŽE volat MCP tools pro ověření stavu:
 * - search_knowledge_v2 pro hledání podobných/konfliktních pravidel
 * - get_knowledge_stats pro celkový stav KB
 */
const evaluation = $input.first().json;
const change = $('Parse Change Event').item.json;

// Build context gap report
const gapReport = {
  ...evaluation,

  // Surface areas to verify with expert
  surface_for_expert: [],

  // Auto-detectable gaps
  detected_gaps: []
};

// Check: deleted rule might leave orphaned references
if (change.action === 'DELETE') {
  gapReport.detected_gaps.push({
    type: 'orphaned_reference',
    description: `Smazané pravidlo '${change.sourceSlug}' může být referencováno v story_rulesets nebo compose_context`,
    suggestion: 'Ověřit story_rulesets.rule_ids a odebrat reference'
  });
}

// Check: security category change needs compliance review
if (change.category === 'security_practice') {
  gapReport.surface_for_expert.push({
    question: `Změna v bezpečnostním pravidle '${change.title}' — odpovídá aktuálnímu threat modelu projektu?`,
    context: 'Security rules mění chování RLS policies a audit journal pattern',
    urgency: 'HIGH'
  });
}

// Check: if sync failed, knowledge might be stale in Ragnarok
if (!evaluation.ragnarok_sync || evaluation.ragnarok_sync === 'FAILED') {
  gapReport.detected_gaps.push({
    type: 'sync_failure',
    description: 'Ragnarok KB neodpovídá aktuálnímu stavu Supabase — vyhledávání vrací zastaralá data',
    suggestion: 'Spustit manuální reseed: node scripts/seed-ragnarok.mjs'
  });
  gapReport.surface_for_expert.push({
    question: 'Ragnarok sync selhal — má se pokusit o retry nebo notifikovat správce?',
    urgency: 'MEDIUM'
  });
}

// Always: suggest expert validates overall direction
if (evaluation.needs_expert_review) {
  gapReport.surface_for_expert.push({
    question: `Změna '${change.title}' (${change.action}) — je v souladu s aktuálním směrem platformy?`,
    context: `Category: ${change.category}, Tags: ${(change.tags || []).join(', ')}`,
    urgency: evaluation.severity
  });
}

return [{ json: gapReport }];

/**
 * Low-risk change auto-approved.
 * Log the decision and close the flow.
 */
const report = $input.first().json;

return [{
  json: {
    status: 'auto_approved',
    change: report.change_summary,
    severity: report.severity,
    ragnarok_sync: report.ragnarok_sync,
    message: `KB změna '${report.change_summary}' automaticky schválena (severity: ${report.severity}, žádné kritické mezery)`,
    closed_at: new Date().toISOString()
  }
}];
